// List of target prospect or client domains to audit
const targetDomains = [
  { domain: 'linear.app', clientName: 'Linear Orbit' },
  { domain: 'stripe.com', clientName: 'Stripe Payments' },
  { domain: 'notion.so', clientName: 'Notion Labs' }
];

return targetDomains.map(item => ({
  json: {
    domain: item.domain,
    clientName: item.clientName,
    auditDate: new Date().toISOString()
  }
}));

const item = $input.first().json;
const domain = item.domain || 'unknown';
const findings = item.findings || [];
const readiness = item.seo_readiness || {};
const score = readiness.score !== undefined ? readiness.score : 100;

// Categorize findings
const criticals = findings.filter(f => f.severity === 'high');
const warnings = findings.filter(f => f.severity === 'medium');
const recommendations = findings.filter(f => f.severity === 'low');

const hasMissingCanonical = findings.some(f => f.code === 'missing_canonical');
const hasLlmsTxt = Boolean(item.llms_txt_present);
const sitemapUrls = item.sitemap_urls_found || 0;

let healthTier = 'EXCELLENT';
if (criticals.length > 0 || hasMissingCanonical) {
  healthTier = 'CRITICAL_ACTION_REQUIRED';
} else if (warnings.length > 0 || !hasLlmsTxt) {
  healthTier = 'OPTIMIZATION_OPPORTUNITY';
}

// Generate ready-to-send Markdown Audit Summary
let summaryMarkdown = `## Technical SEO & AI Readiness Audit: ${domain}\n`;
summaryMarkdown += `**Audit Date:** ${new Date().toISOString().split('T')[0]}\n`;
summaryMarkdown += `**Health Tier:** ${healthTier} | **Readiness Score:** ${score}/100\n`;
summaryMarkdown += `**HTTP Status:** ${item.http_status} | **Final Destination:** ${item.final_url || domain}\n`;
summaryMarkdown += `**Canonical URL:** ${item.canonical_url || 'MISSING (Risk of duplicate content)'}\n`;
summaryMarkdown += `**H1 Heading:** ${item.h1 || 'Missing or multiple'}\n`;
summaryMarkdown += `**Sitemap URLs:** ${sitemapUrls} | **/llms.txt (AI Agents):** ${hasLlmsTxt ? 'Present' : 'Not configured'}\n\n`;

if (findings.length > 0) {
  summaryMarkdown += `### Actionable Findings & Fixes:\n`;
  for (const f of findings) {
    summaryMarkdown += `- **[${(f.severity || 'low').toUpperCase()}] ${f.message}**\n`;
    if (f.recommendation) {
      summaryMarkdown += `  *Recommendation:* ${f.recommendation}\n`;
    }
  }
} else {
  summaryMarkdown += `All primary technical SEO checks passed with zero warnings.\n`;
}

return [{
  json: {
    domain,
    healthTier,
    readinessScore: score,
    findingsCount: findings.length,
    criticalCount: criticals.length,
    hasMissingCanonical,
    hasLlmsTxt,
    canonicalUrl: item.canonical_url,
    finalUrl: item.final_url,
    h1: item.h1,
    sitemapUrls,
    popularityTier: item.popularity_tier,
    summaryMarkdown,
    rawFindings: findings
  }
}];

const item = $input.first().json;
// Format a high-converting agency cold outreach pitch or client notification
const emailSubject = `Quick technical SEO fix for ${item.domain} (Missing Canonical / Audit Score: ${item.readinessScore}/100)`;

let emailBody = `Hi team,\n\n`;
emailBody += `We ran a fast technical SEO and AI-readiness diagnostic on ${item.domain}.\n\n`;
emailBody += `Here is your instant audit overview:\n\n`;
emailBody += item.summaryMarkdown;
emailBody += `\nWould you like our agency to push these technical fixes for you this week?\n\nBest regards,\nAgency SEO Team`;

return [{
  json: {
    domain: item.domain,
    emailSubject,
    emailBody,
    readinessScore: item.readinessScore,
    healthTier: item.healthTier,
    summaryMarkdown: item.summaryMarkdown
  }
}];

const item = $input.first().json;
return [{
  json: {
    domain: item.domain,
    status: 'OPTIMAL_CLEAN_HEALTH',
    readinessScore: item.readinessScore,
    message: `${item.domain} passed all technical SEO and AI search checks.`
  }
}];
